\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\usepgfplotslibrary{colormaps}
\pgfplotsset{compat=1.18}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    view={60}{30},
    xlabel={$x$},
    ylabel={$y$},
    zlabel={$z$},
    title={Ellipsoid: $25x^2 + 4y^2 + z^2 = 100$},
    xmax=3, xmin=-3,
    ymax=6, ymin=-6,
    zmax=12, zmin=-12,
    colormap/viridis,
    grid=major,
    width=12cm,
    height=10cm
]
\addplot3[
    surf,
    shader=flat corner,
    samples=20,
    samples y=30,
    domain=0:360,
    y domain=0:180,
    opacity=0.6
] ({2*sin(y deg)*cos(x deg)}, {5*sin(y deg)*cos(x deg)}, {10*cos(y deg)});
\end{axis}
\end{tikzpicture}
\end{document}

